(function (global) {
    "use strict";
    let serial = 0;
    const chapterCounts = {};
    function q(chapterId, difficulty, en, hi, choices, answer, why, whyHi) {
        serial += 1;
        chapterCounts[chapterId] = (chapterCounts[chapterId] || 0) + 1;
        const offset = (serial - 1) % 4;
        const questionId = "M3-" + String(serial).padStart(3, "0");
        const chapter = global.OLEVEL_CATALOG[2].chapters.find(function (entry) { return entry.id === chapterId; });
        const topicIndex = (chapterCounts[chapterId] - 1) % chapter.topics.length;
        const options = choices.map(function (choice, index) { return { id: questionId + "-O" + (index + 1), en: choice[0], hi: choice[1] }; });
        const ordered = options.slice(offset).concat(options.slice(0, offset));
        return { id: questionId, moduleId: "M3-R5.1", chapterId: chapterId, topicId: chapterId + "-topic-" + (topicIndex + 1), topic: chapter.topics[topicIndex], difficulty: difficulty, questionEnglish: en, questionHindi: hi, options: ordered, correctOptionId: options[answer].id, explanationEnglish: why, explanationHindi: whyHi, sourceType: "Original Practice", source: { name: "ZeroKB original practice", year: null } };
    }
    global.OLEVEL_BANKS = global.OLEVEL_BANKS || {};
    global.OLEVEL_BANKS.m3 = [
        q("programming-basics", "Moderate", "A programmer repeatedly copies the same calculation into several parts of a solution. Which design improvement most directly reduces this duplication?", "प्रोग्रामर एक ही गणना को समाधान के कई हिस्सों में बार-बार कॉपी करता है। कौन-सा डिज़ाइन सुधार इस दोहराव को सीधे घटाएगा?", [["Extract the calculation into a reusable function", "गणना को पुनः उपयोग योग्य function में रखें"], ["Add more comments to each copy", "हर प्रति में अधिक comments जोड़ें"], ["Rename the copied variables", "कॉपी किए गए variables के नाम बदलें"], ["Convert the calculation into a screenshot", "गणना को screenshot में बदलें"]], 0, "A function gives the calculation one maintained implementation that can be called wherever it is needed.", "Function गणना का एक ही रखरखाव-योग्य कार्यान्वयन देता है जिसे आवश्यकता पर बुलाया जा सकता है।"),
        q("programming-basics", "Hard", "A defect appears only for one unusual input. Which debugging practice gives the strongest evidence about the cause?", "एक दोष केवल किसी असामान्य input पर आता है। कारण का सबसे मजबूत प्रमाण कौन-सी debugging विधि देगी?", [["Reproduce the case, inspect relevant state, and isolate the smallest failing condition", "स्थिति दोहराएँ, संबंधित state देखें और सबसे छोटी विफल शर्त अलग करें"], ["Change several unrelated lines and rerun once", "कई असंबंधित पंक्तियाँ बदलकर एक बार चलाएँ"], ["Assume the compiler is at fault", "मान लें कि compiler में दोष है"], ["Delete the test input", "परीक्षण input हटा दें"]], 0, "A reproducible case and controlled inspection distinguish the triggering condition from unrelated code.", "दोहराए जा सकने वाले case और नियंत्रित निरीक्षण से कारण बनने वाली शर्त असंबंधित code से अलग होती है।"),
        q("algorithms-flowcharts", "Moderate", "A flowchart must choose one of two paths depending on whether a value is greater than zero. Which symbol represents this test?", "किसी मान के शून्य से बड़ा होने के आधार पर flowchart को दो रास्तों में से एक चुनना है। इस जाँच को कौन-सा चिह्न दिखाता है?", [["Decision diamond", "निर्णय का हीरा आकार"], ["Input/output parallelogram", "इनपुट/आउटपुट समांतर चतुर्भुज"], ["Process rectangle", "प्रक्रिया आयत"], ["Connector circle only", "केवल connector वृत्त"]], 0, "A decision symbol branches according to the result of a condition.", "Decision symbol शर्त के परिणाम के अनुसार शाखाएँ बनाता है।"),
        q("algorithms-flowcharts", "Hard", "An algorithm scans n values once and performs a fixed number of operations per value. What is its time-growth order?", "एक algorithm n मानों को एक बार scan करता है और हर मान पर निश्चित संख्या में operations करता है। इसकी समय-वृद्धि का क्रम क्या है?", [["O(n)", "O(n)"], ["O(1)", "O(1)"], ["O(n²)", "O(n²)"], ["O(2ⁿ)", "O(2ⁿ)"]], 0, "One constant amount of work for each of n values grows linearly with n.", "n मानों में से प्रत्येक पर निश्चित कार्य करने से कुल कार्य n के साथ रैखिक रूप से बढ़ता है।"),
        q("python-intro", "Moderate", "What does Python's interpreter normally do when it encounters an indentation error in a block?", "ब्लॉक में indentation error मिलने पर Python interpreter सामान्यतः क्या करता है?", [["Reports a syntax/indentation error instead of treating indentation as decoration", "सिर्फ सजावट न मानकर syntax/indentation error बताता है"], ["Silently inserts missing statements", "चुपचाप छूटे statements जोड़ता है"], ["Converts all blocks to comments", "सभी blocks को comments में बदलता है"], ["Runs the block as HTML", "ब्लॉक को HTML की तरह चलाता है"]], 0, "Indentation is part of Python's block syntax and inconsistent indentation is rejected.", "Indentation Python के block syntax का हिस्सा है और असंगत indentation स्वीकार नहीं होती।"),
        q("python-intro", "Hard", "A variable is assigned the value 3 and later the value \"three\". Which statement about Python's typing is accurate?", "एक variable को पहले 3 और बाद में \"three\" मान दिया जाता है। Python typing के बारे में कौन-सा कथन सही है?", [["The name can refer to objects of different types; the objects retain their own types", "नाम अलग-अलग types के objects को संदर्भित कर सकता है; objects के अपने types रहते हैं"], ["The variable permanently becomes an integer after first assignment", "पहले assignment के बाद variable हमेशा integer बन जाता है"], ["Python converts every later string to an integer", "Python बाद की हर string को integer में बदलता है"], ["The second assignment is always a syntax error", "दूसरा assignment हमेशा syntax error है"]], 0, "Python is dynamically typed: names are bound to objects and a later binding may refer to another object type.", "Python dynamically typed है: नाम objects से जुड़ते हैं और बाद में दूसरे type के object से जुड़ सकते हैं।"),
        q("operators-statements", "Easy", "In Python, what value does 17 // 5 produce?", "Python में 17 // 5 का परिणाम क्या होगा?", [["3", "3"], ["3.4", "3.4"], ["2", "2"], ["5", "5"]], 0, "Floor division returns the quotient rounded down to an integer-valued result for these integer operands.", "Floor division इन integer operands के लिए भागफल को नीचे की ओर पूर्णांक मान तक करता है।"),
        q("operators-statements", "Hard", "Consider `False and expensive_check()`. Under Python's short-circuit evaluation, what happens to the function call?", "`False and expensive_check()` पर विचार करें। Python के short-circuit evaluation में function call का क्या होगा?", [["It is not evaluated because the left operand already determines the result", "इसका मूल्यांकन नहीं होता क्योंकि बायाँ operand परिणाम पहले ही तय करता है"], ["It always runs before evaluating False", "False का मूल्यांकन करने से पहले यह हमेशा चलता है"], ["It runs only after the expression is printed", "expression print होने के बाद ही चलता है"], ["It is converted to a string", "इसे string में बदल दिया जाता है"]], 0, "For `and`, a false left operand is sufficient to determine the result, so Python skips the right operand.", "`and` में false बायाँ operand परिणाम तय करने के लिए पर्याप्त है, इसलिए Python दाएँ operand को छोड़ देता है।"),
        q("sequence-types", "Moderate", "What is the result of `\"python\"[1:4]`?", "`\"python\"[1:4]` का परिणाम क्या होगा?", [["yth", "yth"], ["pyt", "pyt"], ["ytho", "ytho"], ["thon", "thon"]], 0, "A slice includes its start index and excludes its stop index, selecting positions 1, 2 and 3.", "Slice में start index शामिल और stop index बाहर रहता है, इसलिए स्थान 1, 2 और 3 चुने जाते हैं।"),
        q("sequence-types", "Hard", "A tuple contains a list: `t = (1, [2, 3])`. Which operation is valid?", "?? tuple ??? list ??: `t = (1, [2, 3])`? ???-?? operation ????? ???", [["Append 4 to t[1]; the list changes though the tuple binding is fixed", "t[1] ??? 4 append ????; tuple binding ????? ???? ??? list ????? ??"], ["Assign a new value to t[0]", "t[0] ?? ??? ??? ???"], ["Append an item directly to t as if it were a list", "t ??? ???? list ?? ??? item append ????"], ["Change the tuple into a dictionary by indexing", "indexing ?? tuple ?? dictionary ?????"]], 0, "A tuple's item references cannot be reassigned, but a referenced mutable list can itself be mutated.", "Tuple ?? item references ???? assign ???? ?? ????, ????? ???????? mutable list ???? ?? ???? ???"),
        q("functions-modules", "Moderate", "Why is `if __name__ == \"__main__\":` commonly used in a Python module?", "Python module में `if __name__ == \"__main__\":` का सामान्य उपयोग क्यों होता है?", [["To run a block only when the file is executed as the main program", "ब्लॉक तभी चलाने के लिए जब फाइल मुख्य प्रोग्राम के रूप में चले"], ["To make every function private", "हर function को private बनाने के लिए"], ["To import the module from the internet", "इंटरनेट से module import करने के लिए"], ["To disable all exceptions", "सभी exceptions बंद करने के लिए"]], 0, "When imported, a module's __name__ is its module name; when run directly, it is set to __main__.", "Import होने पर __name__ module का नाम होता है; सीधे चलाने पर इसका मान __main__ होता है।"),
        q("functions-modules", "Hard", "A function uses a list as a default parameter and appends to it on each call. Why can later calls unexpectedly contain earlier values?", "एक function list को default parameter रखता है और हर call में उसमें append करता है। बाद के calls में पहले के मान अनपेक्षित रूप से क्यों आ सकते हैं?", [["The default list is created once and reused across calls", "Default list एक बार बनती है और calls में पुनः उपयोग होती है"], ["Lists cannot be passed to functions", "Lists functions में नहीं भेजी जा सकतीं"], ["Python copies every default list automatically", "Python हर default list स्वतः कॉपी करता है"], ["The function name is cached as a number", "Function का नाम संख्या के रूप में cache होता है"]], 0, "Mutable default objects are evaluated when the function is defined, not freshly created for every call.", "Mutable default object function परिभाषित होते समय बनता है, हर call पर नया नहीं।"),
        q("numpy-basics", "Moderate", "A NumPy array `a` has shape (2, 3). How many elements does it contain?", "NumPy array `a` का shape (2, 3) है। इसमें कितने elements हैं?", [["6", "6"], ["5", "5"], ["2", "2"], ["3", "3"]], 0, "A 2-by-3 array contains 2 × 3 = 6 elements.", "2-by-3 array में 2 × 3 = 6 elements होते हैं।"),
        q("numpy-basics", "Hard", "A one-dimensional NumPy array of shape (3,) is added to a two-dimensional array of shape (2, 3). Why can the operation work element-wise?", "shape (3,) वाला one-dimensional NumPy array shape (2, 3) वाले two-dimensional array से जोड़ा जाता है। यह operation element-wise क्यों हो सकता है?", [["Broadcasting aligns the trailing dimension of size 3", "Broadcasting आकार 3 वाले अंतिम dimension को align करता है"], ["NumPy silently deletes the first row", "NumPy चुपचाप पहली row हटाता है"], ["All arrays are converted to strings", "सभी arrays strings में बदलते हैं"], ["The arrays must have identical shapes in every operation", "हर operation में arrays के shapes समान होना अनिवार्य है"]], 0, "Broadcasting compares dimensions from the right; sizes match or one side has size 1.", "Broadcasting दाईं ओर से dimensions मिलाता है; आकार बराबर होने चाहिए या किसी एक ओर 1 होना चाहिए।"),
        q("oop", "Moderate", "A subclass supplies its own implementation of a method already defined by its parent class. What is this behavior called?", "Subclass अपने parent class में पहले से परिभाषित method का अपना implementation देता है। इस व्यवहार को क्या कहते हैं?", [["Method overriding", "Method overriding"], ["File buffering", "File buffering"], ["Implicit iteration", "Implicit iteration"], ["Operator precedence", "Operator precedence"]], 0, "Overriding lets a subclass provide specialized behavior for an inherited method.", "Overriding subclass को inherited method के लिए विशेष व्यवहार देने देता है।"),
        q("oop", "Hard", "A class exposes a method for changing an internal value but keeps representation details behind its interface. Which object-oriented principle is most directly illustrated?", "एक class आंतरिक मान बदलने के लिए method देती है लेकिन representation विवरण interface के पीछे रखती है। कौन-सा object-oriented सिद्धांत सीधे दिखता है?", [["Encapsulation", "Encapsulation"], ["Multiple assignment", "Multiple assignment"], ["Sequence slicing", "Sequence slicing"], ["Recursion depth", "Recursion depth"]], 0, "Encapsulation groups state and behavior while controlling access through a defined interface.", "Encapsulation state और behavior को जोड़ता है और परिभाषित interface से पहुँच नियंत्रित करता है।"),
        q("file-processing", "Moderate", "Why is `with open(path) as file:` generally preferred for reading a file?", "फाइल पढ़ने के लिए `with open(path) as file:` को सामान्यतः क्यों प्राथमिकता दी जाती है?", [["The context manager closes the file when the block exits, including on exceptions", "Context manager block से निकलने पर, exception होने पर भी, फाइल बंद करता है"], ["It encrypts the file automatically", "यह फाइल स्वतः encrypt करता है"], ["It prevents all read errors", "यह सभी read errors रोकता है"], ["It makes the file permanently read-only", "यह फाइल को स्थायी रूप से read-only करता है"]], 0, "The file context manager guarantees cleanup when control leaves the block.", "File context manager block से control निकलने पर cleanup सुनिश्चित करता है।"),
        q("file-processing", "Hard", "A program opens an existing text file in write mode (`\"w\"`) and writes a short report. What happens to the previous contents?", "एक प्रोग्राम मौजूदा text file को write mode (`\"w\"`) में खोलकर छोटी रिपोर्ट लिखता है। पुराने contents का क्या होता है?", [["The file is truncated before the new content is written", "नया content लिखने से पहले फाइल truncate होती है"], ["New content is always added after the old content", "नया content हमेशा पुराने के बाद जुड़ता है"], ["The file is opened read-only", "फाइल read-only खुलती है"], ["Only the final line is replaced", "केवल अंतिम पंक्ति बदलती है"]], 0, "Write mode creates a file if needed and truncates an existing file; append mode is used to add at the end.", "Write mode आवश्यकता पर फाइल बनाता है और मौजूदा फाइल truncate करता है; अंत में जोड़ने के लिए append mode है।"),
        q("programming-basics", "Moderate", "A function should accept valid percentages from 0 through 100. Which pair of boundary tests is most useful for detecting an off-by-one error?", "एक function को 0 से 100 तक मान्य percentages स्वीकार करने हैं। Off-by-one error पकड़ने के लिए कौन-सा boundary test pair उपयोगी है?", [["Test 0 and 100, then also the adjacent invalid values -1 and 101", "0 और 100 जाँचें, फिर पास के अमान्य मान -1 और 101 भी"], ["Test only 50 twice", "केवल 50 को दो बार जाँचें"], ["Test a random value above 100 only", "केवल 100 से बड़ा random मान जाँचें"], ["Test an empty file instead of numeric inputs", "संख्यात्मक inputs की जगह खाली file जाँचें"]], 0, "Boundary and just-outside values exercise both inclusive limits and rejection behavior.", "Boundary और उनके ठीक बाहर के मान दोनों inclusive सीमाएँ और rejection behavior जाँचते हैं।"),
        q("algorithms-flowcharts", "Hard", "A sorted array is searched by repeatedly comparing the target with the middle element and discarding half the remaining interval. Which search is described?", "Sorted array में target की तुलना middle element से बार-बार करके शेष interval का आधा हटाया जाता है। कौन-सी search वर्णित है?", [["Binary search", "Binary search"], ["Linear search", "Linear search"], ["Depth-first traversal", "Depth-first traversal"], ["Insertion sort", "Insertion sort"]], 0, "Binary search halves the search interval each step and requires ordered data.", "Binary search हर चरण में search interval आधा करती है और क्रमबद्ध डेटा माँगती है।"),
        q("python-intro", "Easy", "A program reads a number using Python's `input()` and then tries to add 2. Why can `int(input_value)` be necessary?", "Python में `input()` से number पढ़ने के बाद program 2 जोड़ता है। `int(input_value)` क्यों आवश्यक हो सकता है?", [["input() returns text, so conversion is needed for numeric addition", "input() text लौटाता है, इसलिए संख्यात्मक जोड़ के लिए conversion चाहिए"], ["input() always returns a floating-point value", "input() हमेशा floating-point मान देता है"], ["Python cannot add integers", "Python integers नहीं जोड़ सकता"], ["int() sorts the entered characters", "int() दर्ज characters को sort करता है"]], 0, "input() returns a string; parsing it converts numeric text to an integer object.", "input() string लौटाता है; उसे parse करने से numeric text integer object बनता है।"),
        q("operators-statements", "Hard", "A loop should stop as soon as a search finds the first matching record. Which statement exits that loop immediately?", "Search में पहला matching record मिलते ही loop रुकना चाहिए। कौन-सा statement loop से तुरंत बाहर निकलता है?", [["break", "break"], ["continue", "continue"], ["pass", "pass"], ["return only from the outer module", "केवल बाहरी module से return"]], 0, "break terminates the nearest enclosing loop; continue skips to its next iteration.", "break निकटतम loop समाप्त करता है; continue अगली iteration पर जाता है।"),
        q("sequence-types", "Moderate", "Two variables refer to the same list. After `second = first`, an item is appended through `second`. What does `first` observe?", "दो variables एक ही list को refer करते हैं। `second = first` के बाद `second` से item append किया जाता है। `first` में क्या दिखेगा?", [["The appended item, because both names refer to the same list object", "जोड़ा गया item, क्योंकि दोनों नाम उसी list object को refer करते हैं"], ["No change, because assignment copies every list", "कोई बदलाव नहीं, क्योंकि assignment हर list copy करता है"], ["A tuple conversion", "Tuple में conversion"], ["A syntax error from aliasing", "Aliasing के कारण syntax error"]], 0, "Assignment binds another name to the same mutable list; it does not make a shallow or deep copy.", "Assignment दूसरे नाम को उसी mutable list से बाँधता है; यह shallow या deep copy नहीं बनाता।"),
        q("functions-modules", "Easy", "A function calculates a value but reaches its end without a `return` statement. What does the caller receive in Python?", "एक function मान निकालता है लेकिन `return` statement के बिना समाप्त होता है। Python में caller को क्या मिलता है?", [["None", "None"], ["The last local variable automatically", "अंतिम local variable स्वतः"], ["Zero for every function", "हर function के लिए zero"], ["The function's source code", "Function का source code"]], 0, "A Python function returns None when it reaches its end without returning another value.", "जब Python function किसी अन्य मान को लौटाए बिना समाप्त होता है तो वह None लौटाता है।"),
        q("numpy-basics", "Hard", "A NumPy array has shape (4, 3). What shape results from summing along axis 0 without keeping dimensions?", "NumPy array का shape (4, 3) है। Dimensions बनाए बिना axis 0 पर sum करने से कौन-सा shape मिलेगा?", [["(3,)", "(3,)"], ["(4,)", "(4,)"], ["(4, 3)", "(4, 3)"], ["()", "()"]], 0, "Summing axis 0 reduces the four rows and leaves one result for each of the three columns.", "Axis 0 पर जोड़ने से चार rows घटती हैं और तीन columns में प्रत्येक के लिए एक परिणाम बचता है।"),
        q("oop", "Moderate", "A class defines `__init__(self, name)` and assigns the argument to `self.name`. When is this initializer normally called?", "एक class `__init__(self, name)` define करके argument को `self.name` में रखती है। यह initializer सामान्यतः कब चलता है?", [["When a new instance is created", "नया instance बनाते समय"], ["Every time any class method is read", "हर class method पढ़ते समय"], ["Only when the object is deleted", "केवल object हटाते समय"], ["When the module is imported, once for every possible object", "Module import पर हर संभावित object के लिए एक बार"]], 0, "__init__ initializes instance state as part of creating a new object.", "__init__ नया object बनाते समय instance state initialize करता है।"),
        q("file-processing", "Moderate", "A text file contains several lines and a program must process each line without loading the entire file into a list first. Which approach is suitable?", "Text file में कई पंक्तियाँ हैं और program को पूरी file पहले list में लाए बिना प्रत्येक पंक्ति process करनी है। कौन-सा तरीका उपयुक्त है?", [["Iterate over the open file object line by line", "Open file object पर line by line iterate करें"], ["Call readlines() and retain every line before processing", "Processing से पहले readlines() से हर line रखें"], ["Open the file in write mode", "File को write mode में खोलें"], ["Convert the file path to a tuple", "File path को tuple में बदलें"]], 0, "File iteration yields lines incrementally and avoids storing the entire file's lines at once.", "File iteration पंक्तियाँ क्रमशः देती है और पूरी file की lines एक साथ रखने से बचाती है।"),
        q("operators-statements", "Moderate", "For integer n, what does `n % 2 == 0` test?", "Integer n के लिए `n % 2 == 0` क्या जाँचता है?", [["Whether n is even", "क्या n सम है"], ["Whether n is negative", "क्या n ऋणात्मक है"], ["Whether n is text", "क्या n text है"], ["Whether n is prime", "क्या n prime है"]], 0, "An even integer has remainder zero when divided by two.", "सम integer को दो से भाग देने पर शेषफल शून्य होता है।", "Expected Practice"),
        q("operators-statements", "Moderate", "Which operator tests two values for equality in a Python condition?", "Python condition में दो मानों की समानता कौन-सा operator जाँचता है?", [["==", "=="], ["=", "="], ["//", "//"], ["**", "**"]], 0, "The equality comparison is ==; a single = assigns a value to a name.", "Equality comparison == है; एकल = नाम को मान assign करता है।", "Expected Practice"),
        q("operators-statements", "Moderate", "What is the value of `not (True or False)`?", "`not (True or False)` का मान क्या होगा?", [["False", "False"], ["True", "True"], ["None", "None"], ["2", "2"]], 0, "The parenthesized or expression is True, and not reverses that truth value.", "कोष्ठक वाला or expression True है और not उसे उलट देता है।", "Expected Practice"),
        q("operators-statements", "Moderate", "A counter is 6. What value does it hold after `counter += 3`?", "Counter 6 है। `counter += 3` के बाद उसका मान क्या होगा?", [["9", "9"], ["3", "3"], ["18", "18"], ["6", "6"]], 0, "Augmented addition adds to the existing value and assigns the result back.", "Augmented addition मौजूदा मान में जोड़कर परिणाम वापस assign करता है।", "Expected Practice"),
        q("operators-statements", "Moderate", "A loop should continue while a counter is below 5. Which condition expresses this?", "एक loop को counter के 5 से कम रहने तक जारी रहना चाहिए। कौन-सी condition यह व्यक्त करती है?", [["counter < 5", "counter < 5"], ["counter == 5", "counter == 5"], ["counter > 5", "counter > 5"], ["counter = 5 (assignment, not comparison)", "counter = 5 (assignment, ????? ????)"]], 0, "The strict comparison is true below 5 and becomes false when the counter reaches 5.", "Strict comparison 5 से नीचे true और counter के 5 पर पहुँचने पर false होती है।", "Expected Practice"),
        q("operators-statements", "Hard", "What is `2 + 3 * 4 ** 2` under Python arithmetic precedence?", "Python arithmetic precedence के अनुसार `2 + 3 * 4 ** 2` का मान क्या है?", [["50", "50"], ["400", "400"], ["80", "80"], ["196", "196"]], 0, "Exponentiation gives 16, multiplication gives 48, and addition then gives 50.", "Exponentiation 16, multiplication 48 और फिर addition 50 देता है।", "Expected Practice"),
        q("operators-statements", "Hard", "Which expression is equivalent to `x >= 10 and x <= 20` in Python?", "Python में `x >= 10 and x <= 20` के बराबर expression कौन-सा है?", [["10 <= x <= 20", "10 <= x <= 20"], ["x < 10 or x > 20", "x < 10 or x > 20"], ["x == 10 and x == 20", "x == 10 and x == 20"], ["Invalid chained expression: 10 => x => 20", "?????? chained expression: 10 => x => 20"]], 0, "A chained comparison requires x to satisfy both bounds.", "Chained comparison में x को दोनों सीमाएँ पूरी करनी होती हैं।", "Expected Practice"),
        q("operators-statements", "Hard", "A loop should skip the remaining statements for this item but process later items. Which statement is appropriate?", "Loop को इस item के शेष statements छोड़कर बाद के items process करने हैं। कौन-सा statement उचित है?", [["continue", "continue"], ["break", "break"], ["pass", "pass"], ["else", "else"]], 0, "continue advances to the next iteration, whereas break terminates the loop.", "continue अगली iteration पर जाता है, जबकि break loop समाप्त करता है।", "Expected Practice"),
        q("sequence-types", "Moderate", "For `items = [10, 20, 30]`, which value does `items[-1]` select?", "`items = [10, 20, 30]` में `items[-1]` कौन-सा मान चुनता है?", [["30, the last element", "30, अंतिम element"], ["10, the first element", "10, पहला element"], ["3, the length", "3, लंबाई"], ["An empty list", "खाली list"]], 0, "Index -1 addresses the final element of a sequence.", "Index -1 sequence के अंतिम element को दर्शाता है।", "Expected Practice"),
        q("sequence-types", "Moderate", "A list should receive every element of another list as a separate item. Which method should be used?", "एक list में दूसरी list के हर element को अलग item की तरह जोड़ना है। कौन-सा method उपयोग करें?", [["extend()", "extend()"], ["append()", "append()"], ["clear()", "clear()"], ["pop()", "pop()"]], 0, "extend adds each item from an iterable; append would add the whole list as one nested item.", "extend iterable के items अलग जोड़ता है; append पूरी list को एक nested item बनाता है।", "Expected Practice"),
        q("sequence-types", "Moderate", "What happens if a program tries indexed assignment to change one character of a Python string?", "Python string का एक character indexed assignment से बदलने की कोशिश करने पर क्या होता है?", [["It is not allowed because strings are immutable", "Strings immutable होने के कारण यह अनुमत नहीं"], ["Only even positions can be changed", "केवल even positions बदल सकते हैं"], ["The string becomes a list automatically", "String स्वतः list बन जाती है"], ["Only the first character changes", "केवल पहला character बदलता है"]], 0, "Strings are immutable; a modified value must be constructed as a new string.", "Strings immutable हैं; बदला हुआ मान नई string बनाकर तैयार करना पड़ता है।", "Expected Practice"),
        q("sequence-types", "Moderate", "What does the sequence expression `\"ha\" * 3` produce?", "Sequence expression `\"ha\" * 3` क्या बनाता है?", [["\"hahaha\"", "\"hahaha\""], ["\"ha3\"", "\"ha3\""], ["\"hhh aaa\"", "\"hhh aaa\""], ["A three-item tuple", "तीन items वाला tuple"]], 0, "Sequence repetition repeats the string contents three times.", "Sequence repetition string की सामग्री तीन बार दोहराता है।", "Expected Practice"),
        q("sequence-types", "Moderate", "Which expression tests whether `target` occurs in sequence `data`?", "कौन-सा expression जाँचता है कि `target`, sequence `data` में है?", [["target in data", "target in data"], ["target is data", "target is data"], ["data has target", "data has target"], ["data[target]", "data[target]"]], 0, "The in operator performs a membership test on a sequence.", "in operator sequence में membership जाँचता है।", "Expected Practice"),
        q("sequence-types", "Hard", "What list results from `[0, 1, 2, 3, 4, 5][::2]`?", "`[0, 1, 2, 3, 4, 5][::2]` से कौन-सी list बनती है?", [["[0, 2, 4]", "[0, 2, 4]"], ["[1, 3, 5]", "[1, 3, 5]"], ["[0, 1]", "[0, 1]"], ["[5, 3, 1]", "[5, 3, 1]"]], 0, "Step 2 selects every second element starting from index zero.", "Step 2 index zero से हर दूसरा element चुनता है।", "Expected Practice"),
        q("sequence-types", "Hard", "Why is modifying a list while directly iterating over it error-prone?", "List पर सीधे iterate करते हुए उसे बदलना त्रुटि-प्रवण क्यों है?", [["Position changes may cause items to be skipped or revisited", "Positions बदलने से items छूट या दोबारा देखे जा सकते हैं"], ["Python prohibits any mutation", "Python हर mutation रोकता है"], ["The list becomes a tuple", "List tuple बन जाती है"], ["The loop counter becomes a float", "Loop counter float बन जाता है"]], 0, "Mutation can change traversal positions; iterating over a copy or building a new list is safer.", "Mutation traversal positions बदल सकती है; copy पर iterate करना या नई list बनाना सुरक्षित है।", "Expected Practice"),
        q("sequence-types", "Hard", "For a tuple to be used as a dictionary key, what must be true of its contents?", "Tuple को dictionary key बनाने के लिए उसकी सामग्री के बारे में क्या सत्य होना चाहिए?", [["Every contained element is hashable", "उसका हर element hashable हो"], ["It contains a list", "उसमें list हो"], ["All elements are integers", "सभी elements integer हों"], ["It is first converted to text", "पहले उसे text में बदलें"]], 0, "A tuple is hashable only when all its elements are hashable; a contained list prevents this.", "Tuple तभी hashable है जब उसके सभी elements hashable हों; भीतर की list इसे रोकती है।", "Expected Practice"),
        q("functions-modules", "Moderate", "A function has parameters `(width, height)` and is called with `height=4, width=3`. Why is the argument order valid?", "Function के parameters `(width, height)` हैं और call में `height=4, width=3` है। Argument क्रम मान्य क्यों है?", [["Keyword arguments identify their parameters by name", "Keyword arguments parameter को नाम से पहचानते हैं"], ["Python sorts arguments alphabetically", "Python arguments को alphabetical क्रम में sort करता है"], ["Parameter names are ignored", "Parameter नाम अनदेखे होते हैं"], ["The function body is reordered", "Function body का क्रम बदल जाता है"]], 0, "Keyword arguments bind values by parameter name, so their order can differ.", "Keyword arguments मानों को parameter नाम से जोड़ते हैं, इसलिए उनका क्रम अलग हो सकता है।", "Expected Practice"),
        q("functions-modules", "Moderate", "A name assigned inside a function without a `global` declaration normally belongs to which scope?", "`global` declaration के बिना function के भीतर assign किया गया नाम सामान्यतः किस scope में होता है?", [["Local scope of that function", "उस function का local scope"], ["Every module", "हर module"], ["All Python processes", "सभी Python processes"], ["The operating-system shell", "Operating-system shell"]], 0, "Names assigned in a function body are local unless a scope declaration changes that rule.", "Function body में assign नाम local होते हैं, जब तक scope declaration नियम न बदले।", "Expected Practice"),
        q("functions-modules", "Moderate", "A function computes a numeric result that its caller must use. What should the function do?", "Function एक numeric result निकालता है जिसे caller उपयोग करेगा। Function को क्या करना चाहिए?", [["Return the value", "मान return करना"], ["Only print it", "केवल उसे print करना"], ["Place it in a comment", "उसे comment में रखना"], ["Import its caller", "अपने caller को import करना"]], 0, "return makes the result available to the caller; print only displays it.", "return परिणाम caller को उपलब्ध कराता है; print केवल उसे दिखाता है।", "Expected Practice"),
        q("functions-modules", "Moderate", "After `import statistics as stats`, how is the module's `mean` function accessed?", "`import statistics as stats` के बाद module का `mean` function कैसे उपयोग होगा?", [["stats.mean(...)", "stats.mean(...)"], ["statistics.mean(...) only", "केवल statistics.mean(...)"], ["mean.stats(...)", "mean.stats(...)"], ["import.mean(...)", "import.mean(...)"]], 0, "The import alias stats is the name used to access the module's members.", "Import alias stats module के members तक पहुँचने का नाम है।", "Expected Practice"),
        q("functions-modules", "Moderate", "What is the main purpose of a docstring immediately inside a function definition?", "Function definition के तुरंत भीतर docstring का मुख्य उद्देश्य क्या है?", [["Document behavior and be available for introspection", "व्यवहार document करना और introspection के लिए उपलब्ध होना"], ["Execute as a return statement", "Return statement की तरह चलना"], ["Make all parameters optional", "सभी parameters optional बनाना"], ["Import the function everywhere", "Function को हर जगह import करना"]], 0, "A docstring documents a function and is stored as its documentation string.", "Docstring function को document करती है और documentation string के रूप में संग्रहीत होती है।", "Expected Practice"),
        q("functions-modules", "Hard", "A recursive function reduces a positive integer each call. What must its reachable base case do?", "Recursive function हर call में positive integer घटाता है। उसके पहुँचने योग्य base case को क्या करना चाहिए?", [["Return without making another recursive call", "एक और recursive call किए बिना return करना"], ["Increase the integer forever", "Integer हमेशा बढ़ाना"], ["Repeat the call with the same value", "उसी मान से call दोहराना"], ["Import itself each time", "हर बार स्वयं को import करना"]], 0, "A base case ends recursion; without one, calls continue until a recursion error.", "Base case recursion समाप्त करता है; इसके बिना calls recursion error तक जारी रहते हैं।", "Expected Practice"),
        q("functions-modules", "Hard", "A tax rate is usually standard but should be overridable for some callers. Which parameter design suits this?", "Tax rate सामान्यतः standard है लेकिन कुछ callers इसे बदल सकें। कौन-सा parameter design सही है?", [["Provide a default parameter value callers may override", "Default parameter value दें जिसे caller बदल सके"], ["Hard-code a separate function for every rate", "हर rate के लिए अलग function hard-code करें"], ["Guess a caller's local variable name", "Caller के local variable का नाम अनुमानें"], ["Require a positional value in all cases", "हर स्थिति में positional value अनिवार्य करें"]], 0, "A default handles the common case while explicit arguments support exceptions.", "Default सामान्य स्थिति संभालता है और explicit argument अपवादों को समर्थन देता है।", "Expected Practice"),
        q("functions-modules", "Hard", "A module's demonstration should run directly but not on import. How should its call be guarded?", "Module का demonstration direct run पर चले लेकिन import पर नहीं। Call को कैसे guard करें?", [["Put it under `if __name__ == \"__main__\":`", "`if __name__ == \"__main__\":` के नीचे रखें"], ["Put it at every module's top level", "हर module के top level पर रखें"], ["Prefix every function with underscore", "हर function के आगे underscore लगाएँ"], ["Copy its source into importers", "Import करने वालों में source copy करें"]], 0, "The main guard runs only when the file is executed as the main program.", "Main guard केवल file को मुख्य program की तरह चलाने पर execute होता है।", "Expected Practice"),
        q("programming-basics", "Moderate", "Which analysis method separates a task into data received, work performed, and result produced?", "कौन-सी विश्लेषण विधि कार्य को प्राप्त डेटा, किए गए काम और परिणाम में बाँटती है?", [["Input-process-output", "इनपुट-प्रक्रिया-आउटपुट"], ["Trial-and-error coding", "परीक्षण-त्रुटि कोडिंग"], ["Object serialization", "Object serialization"], ["Memory allocation", "Memory allocation"]], 0, "Input-process-output analysis makes a requirement concrete by identifying its inputs, processing, and outputs.", "इनपुट-प्रक्रिया-आउटपुट विश्लेषण inputs, processing और outputs पहचानकर आवश्यकता स्पष्ट करता है।", "Expected Practice"),
        q("programming-basics", "Moderate", "A program follows its specification exactly, but users say the specification solves the wrong problem. Which activity should have caught this?", "Program specification का ठीक पालन करता है, लेकिन users कहते हैं कि specification गलत समस्या हल करती है। इसे कौन-सी गतिविधि पकड़नी चाहिए थी?", [["Validation against user needs", "उपयोगकर्ता की ज़रूरतों से validation"], ["Compilation", "Compilation"], ["Variable declaration", "Variable declaration"], ["Source formatting", "Source formatting"]], 0, "Validation checks whether the specified solution meets the real need, not just whether it was implemented correctly.", "Validation जाँचता है कि निर्दिष्ट समाधान वास्तविक आवश्यकता पूरी करता है या नहीं, केवल सही implementation नहीं।", "Expected Practice"),
        q("programming-basics", "Moderate", "A complex formula is difficult for a future maintainer to interpret. What should an adjacent comment explain?", "एक जटिल formula को भविष्य के maintainer के लिए समझना कठिन है। पास का comment क्या समझाए?", [["Its purpose and important assumptions", "उसका उद्देश्य और महत्वपूर्ण मान्यताएँ"], ["The same formula copied word for word", "वही formula शब्दशः दोहराकर"], ["The author's unrelated preferences", "लेखक की असंबंधित पसंद"], ["The computer's model number", "Computer का model number"]], 0, "A useful comment supplies rationale and assumptions that are not obvious from the expression itself.", "उपयोगी comment वह कारण और मान्यताएँ बताता है जो expression से स्पष्ट नहीं हैं।", "Expected Practice"),
        q("programming-basics", "Moderate", "Boundary tests cover the minimum and maximum permitted inputs. What complementary test category should also be included?", "Boundary tests न्यूनतम और अधिकतम अनुमत inputs जाँचते हैं। इनके साथ कौन-सी परीक्षण श्रेणी भी होनी चाहिए?", [["Representative ordinary cases", "प्रतिनिधि सामान्य cases"], ["Only malformed source files", "केवल गलत source files"], ["Repeated tests of one boundary", "एक boundary के बार-बार tests"], ["Tests with no expected result", "बिना अपेक्षित परिणाम वाले tests"]], 0, "Typical valid inputs verify normal behavior in addition to edge conditions.", "सामान्य valid inputs किनारी स्थितियों के साथ सामान्य व्यवहार भी verify करते हैं।", "Expected Practice"),
        q("programming-basics", "Moderate", "A large task is divided into input, calculation, and reporting components. What is the main advantage?", "बड़े कार्य को input, calculation और reporting components में बाँटा जाता है। मुख्य लाभ क्या है?", [["Each part has a clear responsibility and can be checked separately", "हर भाग की स्पष्ट जिम्मेदारी है और उसे अलग जाँचा जा सकता है"], ["Testing is no longer needed", "Testing की आवश्यकता नहीं रहती"], ["Every component must use global variables", "हर component में global variables अनिवार्य हैं"], ["The original requirements can be discarded", "मूल आवश्यकताएँ हटाई जा सकती हैं"]], 0, "Decomposition reduces complexity and makes component-level reasoning and verification possible.", "Decomposition जटिलता घटाता है और component स्तर पर विचार तथा verification संभव करता है।", "Expected Practice"),
        q("programming-basics", "Hard", "Two designs meet the output requirement, but one duplicates logic and the other centralizes it. What is the fairest basis for selecting a design?", "दो designs output requirement पूरी करते हैं, पर एक logic दोहराता है और दूसरा केंद्रीकृत करता है। चुनाव का सबसे उचित आधार क्या है?", [["Compare correctness, maintainability, and resource trade-offs against requirements", "आवश्यकताओं के अनुसार correctness, maintainability और संसाधन trade-offs की तुलना"], ["Choose only by shortest source length", "केवल सबसे छोटे source के आधार पर चुनें"], ["Choose the design with most comments", "सबसे अधिक comments वाला design चुनें"], ["Avoid evaluating either implementation", "किसी implementation का मूल्यांकन न करें"]], 0, "A sound choice considers requirements and relevant trade-offs rather than a single superficial measure.", "उचित चुनाव केवल सतही माप के बजाय आवश्यकताओं और संबंधित trade-offs पर विचार करता है।", "Expected Practice"),
        q("programming-basics", "Hard", "A defect report must be reproducible while protecting user privacy. Which diagnostic evidence is most appropriate?", "दोष रिपोर्ट को पुनरुत्पादित करना है और उपयोगकर्ता की गोपनीयता भी बचानी है। कौन-सा diagnostic evidence उपयुक्त है?", [["A minimal anonymized failing case plus the program version", "न्यूनतम anonymized failing case और program version"], ["All user passwords and profiles", "सभी user passwords और profiles"], ["A developer's guess without execution details", "Execution details के बिना developer का अनुमान"], ["No recorded information at all", "कोई जानकारी दर्ज न करना"]], 0, "A minimal anonymized case and version help reproduce failure without retaining unnecessary personal data.", "न्यूनतम anonymized case और version अनावश्यक निजी data रखे बिना failure दोहराने में मदद करते हैं।", "Expected Practice"),
        q("programming-basics", "Hard", "Two components disagree about a date field's format and valid range. What prevents this integration defect most effectively?", "दो components date field के format और valid range पर असहमत हैं। इस integration defect को सबसे प्रभावी रूप से क्या रोकेगा?", [["A documented shared interface contract", "Documented साझा interface contract"], ["Independent undocumented assumptions", "स्वतंत्र undocumented मान्यताएँ"], ["Removing date tests", "Date tests हटाना"], ["Renaming both components", "दोनों components का नाम बदलना"]], 0, "A shared contract aligns assumptions where components exchange data.", "साझा contract उस बिंदु पर मान्यताओं को एकसमान करता है जहाँ components data साझा करते हैं।", "Expected Practice"),
        q("algorithms-flowcharts", "Moderate", "A procedure must examine every item of a finite list once and then stop. Which property ensures termination?", "एक procedure को सीमित सूची का हर item एक बार जाँचकर रुकना है। कौन-सा गुण termination सुनिश्चित करता है?", [["A finite bound that advances toward a stopping condition", "Stopping condition की ओर बढ़ती सीमित सीमा"], ["A repeated branch that never changes state", "State न बदलने वाली दोहराई branch"], ["An unconditional return to the first step", "पहले चरण पर बिना शर्त वापसी"], ["A decision with no exit path", "Exit path के बिना decision"]], 0, "Progress toward a finite stopping condition prevents the process from continuing indefinitely.", "सीमित stopping condition की ओर प्रगति प्रक्रिया को अनिश्चित काल चलने से रोकती है।", "Expected Practice"),
        q("algorithms-flowcharts", "Moderate", "A flowchart connector avoids a long line crossing several other paths. What does it chiefly improve?", "Flowchart connector कई paths को काटती लंबी line से बचाता है। यह मुख्यतः क्या सुधारता है?", [["Diagram readability", "Diagram की पठनीयता"], ["Program execution speed", "Program execution speed"], ["Input accuracy", "Input की accuracy"], ["Computer memory capacity", "Computer memory capacity"]], 0, "A connector shows continuation neatly without changing the represented logic.", "Connector दर्शाए गए logic को बदले बिना continuation साफ दिखाता है।", "Expected Practice"),
        q("algorithms-flowcharts", "Moderate", "A procedure chooses a pass action or a fail action, then continues after either one. Which structure fits?", "एक procedure pass या fail action चुनता है, फिर किसी भी action के बाद आगे चलता है। कौन-सी structure सही है?", [["Two-way selection whose branches rejoin", "दो branches वाली selection जो फिर जुड़ती हैं"], ["An infinite loop", "अनंत loop"], ["A sequence without a condition", "Condition-विहीन sequence"], ["Recursion without a base case", "Base case के बिना recursion"]], 0, "Selection chooses a branch based on a condition, and those paths can rejoin afterward.", "Selection condition पर branch चुनती है और वे paths बाद में फिर मिल सकते हैं।", "Expected Practice"),
        q("algorithms-flowcharts", "Moderate", "Breaking “prepare a monthly report” into successively smaller tasks is an example of which method?", "“Monthly report तैयार करें” को क्रमशः छोटे tasks में बाँटना किस विधि का उदाहरण है?", [["Top-down decomposition", "Top-down decomposition"], ["Data coercion", "Data coercion"], ["Random search", "Random search"], ["File buffering", "File buffering"]], 0, "Top-down decomposition refines a broad task into detailed subproblems.", "Top-down decomposition व्यापक कार्य को विस्तृत उप-समस्याओं में बदलता है।", "Expected Practice"),
        q("algorithms-flowcharts", "Moderate", "A loop adds each temperature to a running total. What initial accumulator value is appropriate?", "एक loop हर temperature को running total में जोड़ता है। Accumulator का आरंभिक मान क्या उचित है?", [["0, the additive identity", "0, जोड़ का identity"], ["An undefined value", "Undefined मान"], ["The first temperature twice", "पहला temperature दो बार"], ["A text label", "Text label"]], 0, "Starting a sum at zero makes the accumulator equal to the total processed so far.", "योग शून्य से शुरू करने पर accumulator अब तक process किए गए मानों का कुल होता है।", "Expected Practice"),
        q("algorithms-flowcharts", "Hard", "An algorithm loops through n rows and examines n columns in each row. How does its comparison count grow?", "Algorithm n rows पर loop करता है और हर row में n columns जाँचता है। Comparisons की संख्या कैसे बढ़ती है?", [["Quadratically, proportional to n squared", "Quadratically, n squared के अनुपात में"], ["Linearly, proportional to n", "Linearly, n के अनुपात में"], ["Constantly", "नियत रूप से"], ["Logarithmically", "Logarithmically"]], 0, "The inner n operations repeat for each of n rows, giving n times n work.", "भीतर के n operations प्रत्येक n rows के लिए दोहरते हैं, अर्थात n गुणा n काम।", "Expected Practice"),
        q("algorithms-flowcharts", "Hard", "A loop checks its condition before the body, and the initial condition is false. How many times does the body run?", "Loop body से पहले condition जाँचता है और शुरुआत में condition false है। Body कितनी बार चलेगी?", [["Zero times", "शून्य बार"], ["Once", "एक बार"], ["Twice", "दो बार"], ["Until the program closes", "Program बंद होने तक"]], 0, "A pre-test loop skips its body when its first condition check is false.", "Pre-test loop की पहली condition false होने पर body छोड़ दी जाती है।", "Expected Practice"),
        q("algorithms-flowcharts", "Hard", "A search returns an index on success and a special not-found result otherwise. How should that result be chosen?", "Search सफल होने पर index और अन्यथा विशेष not-found परिणाम देती है। वह परिणाम कैसे चुना जाना चाहिए?", [["Use a documented sentinel outside the valid index range", "Valid index सीमा से बाहर documented sentinel चुनें"], ["Use index zero for both outcomes", "दोनों परिणामों में index zero रखें"], ["Return an unexplained inspected value", "बिना व्याख्या जाँचा गया मान लौटाएँ"], ["Modify the searched list", "खोजी जा रही list बदलें"]], 0, "A sentinel outside all valid indices distinguishes failure from every successful index.", "सभी valid indices से बाहर sentinel विफलता को हर सफल index से अलग करता है।", "Expected Practice"),
        q("python-intro", "Moderate", "Which name follows Python identifier rules and is not a reserved word?", "कौन-सा नाम Python identifier rules का पालन करता है और reserved word नहीं है?", [["total_marks", "total_marks"], ["2nd_mark", "2nd_mark"], ["class", "class"], ["marks.total", "marks.total"]], 0, "An identifier may contain underscores but cannot begin with a digit, contain a hyphen, or be a keyword.", "Identifier में underscore हो सकता है, पर वह digit से शुरू, hyphen युक्त या keyword नहीं हो सकता।", "Expected Practice"),
        q("python-intro", "Moderate", "Which built-in type most directly represents the logical states on and off?", "कौन-सा built-in type चालू और बंद जैसी तार्किक स्थितियों को सीधे दर्शाता है?", [["bool", "bool"], ["float", "float"], ["list", "list"], ["dict", "dict"]], 0, "Boolean values represent the two truth states True and False.", "Boolean मान दो truth states True और False दर्शाते हैं।", "Expected Practice"),
        q("python-intro", "Moderate", "Outside a string literal, what does Python do with text following `#` on a source line?", "String literal के बाहर source line में `#` के बाद के text को Python क्या मानता है?", [["Treat it as a comment", "Comment मानता है"], ["Treat it as an import", "Import मानता है"], ["Treat it as a block terminator", "Block terminator मानता है"], ["Treat it as a variable declaration", "Variable declaration मानता है"]], 0, "A hash outside a string begins a comment whose remainder is ignored on that line.", "String के बाहर hash comment शुरू करता है और उस line का बाकी भाग अनदेखा होता है।", "Expected Practice"),
        q("python-intro", "Moderate", "The text `\"8.5\"` is needed as a decimal number. Which conversion is appropriate?", "Text `\"8.5\"` को decimal number की तरह चाहिए। कौन-सा conversion उचित है?", [["float(\"8.5\")", "float(\"8.5\")"], ["bool(\"8.5\")", "bool(\"8.5\")"], ["list(\"8.5\")", "list(\"8.5\")"], ["str(8.5)", "str(8.5)"]], 0, "float parses numeric text with a decimal point into a floating-point value.", "float दशमलव बिंदु वाले numeric text को floating-point मान में parse करता है।", "Expected Practice"),
        q("python-intro", "Moderate", "At an interactive Python prompt, why may an expression's result appear without an explicit `print()`?", "Interactive Python prompt पर बिना explicit `print()` expression का परिणाम क्यों दिख सकता है?", [["The REPL displays the value of an evaluated expression", "REPL evaluated expression का मान दिखाता है"], ["Every script receives an inserted print call", "हर script में print call स्वतः जुड़ता है"], ["The operating system prints every variable", "Operating system हर variable print करता है"], ["Expressions are comments at the prompt", "Prompt पर expressions comments होते हैं"]], 0, "The interactive shell evaluates entered expressions and displays their values.", "Interactive shell दर्ज expressions evaluate करके उनके मान दिखाता है।", "Expected Practice"),
        q("python-intro", "Hard", "A name is assigned `4` and then `4.0`. Which statement is accurate?", "एक नाम को पहले `4` और फिर `4.0` assign किया जाता है। कौन-सा कथन सही है?", [["They compare numerically equal, though the objects have different types", "वे संख्यात्मक रूप से बराबर हैं, यद्यपि objects के type अलग हैं"], ["They compare unequal because int and float cannot be compared", "int और float compare नहीं हो सकते इसलिए वे असमान हैं"], ["The second assignment is rejected by static typing", "Static typing दूसरा assignment अस्वीकार करती है"], ["Both values become strings", "दोनों मान strings बन जाते हैं"]], 0, "Python permits numeric equality between int and float while preserving their distinct object types.", "Python int और float के बीच numeric equality देता है, पर उनके अलग object types बने रहते हैं।", "Expected Practice"),
        q("python-intro", "Hard", "A saved `.py` file is run with Python. What is the interpreter's essential role?", "सहेजी `.py` file Python से चलाई जाती है। Interpreter की मूल भूमिका क्या है?", [["Execute Python statements according to language rules", "Language rules के अनुसार Python statements चलाना"], ["Guarantee the algorithm is logically correct", "Algorithm की तार्किक correctness की गारंटी देना"], ["Convert the file into a spreadsheet", "File को spreadsheet में बदलना"], ["Eliminate the need for input data", "Input data की आवश्यकता समाप्त करना"]], 0, "An interpreter executes statements, while correctness still depends on program design and tests.", "Interpreter statements चलाता है; correctness फिर भी program design और tests पर निर्भर है।", "Expected Practice"),
        q("python-intro", "Hard", "An integer must be displayed beside explanatory text. What avoids a type error when forming the output?", "Integer को explanatory text के साथ दिखाना है। Output बनाते समय type error से कैसे बचेंगे?", [["Convert it to text or use formatted output", "इसे text में बदलें या formatted output लें"], ["Convert the text to a list", "Text को list में बदलें"], ["Change the indentation", "Indentation बदलें"], ["Use a Boolean operator", "Boolean operator लगाएँ"]], 0, "String concatenation requires text operands; conversion or formatting safely handles the integer.", "String concatenation में text operands चाहिए; conversion या formatting integer को सुरक्षित संभालती है।", "Expected Practice"),
        q("numpy-basics", "Moderate", "Which NumPy constructor creates four consecutive integers starting at zero?", "कौन-सा NumPy constructor शून्य से शुरू होने वाले चार क्रमागत integers बनाता है?", [["np.arange(4)", "np.arange(4)"], ["np.zeros(4)", "np.zeros(4)"], ["np.ones(4)", "np.ones(4)"], ["np.shape(4)", "np.shape(4)"]], 0, "arange(4) produces 0, 1, 2, and 3; zeros and ones produce repeated values.", "arange(4), 0, 1, 2 और 3 देता है; zeros और ones दोहराए मान देते हैं।", "Expected Practice"),
        q("numpy-basics", "Moderate", "For a NumPy array `a`, what information does `a.ndim` provide?", "NumPy array `a` के लिए `a.ndim` कौन-सी जानकारी देता है?", [["The number of axes", "Axes की संख्या"], ["The number of bytes per element", "प्रति element bytes की संख्या"], ["The sum of elements", "Elements का योग"], ["The largest value", "सबसे बड़ा मान"]], 0, "ndim reports the array's number of dimensions; shape gives the size of each axis.", "ndim array के dimensions की संख्या बताता है; shape हर axis का आकार बताता है।", "Expected Practice"),
        q("numpy-basics", "Moderate", "Only array values greater than 10 are needed. Which technique selects them?", "केवल 10 से बड़े array values चाहिए। उन्हें चुनने की कौन-सी तकनीक है?", [["Boolean mask using `a > 10`", "`a > 10` से Boolean mask"], ["Calling `a.shape(10)`", "`a.shape(10)` बुलाना"], ["Changing the array's class", "Array की class बदलना"], ["Using a file pointer", "File pointer उपयोग करना"]], 0, "The comparison creates a Boolean mask that selects matching elements.", "Comparison Boolean mask बनाता है जो matching elements चुनता है।", "Expected Practice"),
        q("numpy-basics", "Moderate", "What shape usually results from transposing a two-dimensional array with shape `(2, 3)`?", "Shape `(2, 3)` वाले two-dimensional array को transpose करने से सामान्यतः कौन-सा shape मिलता है?", [["(3, 2)", "(3, 2)"], ["(2, 3)", "(2, 3)"], ["()", "()"], ["(5,)", "(5,)"]], 0, "Transpose swaps the row and column axes.", "Transpose row और column axes की अदला-बदली करता है।", "Expected Practice"),
        q("numpy-basics", "Moderate", "Why can `a * 2` be preferable to a Python loop for doubling each NumPy array element?", "NumPy array के प्रत्येक element को दोगुना करने के लिए Python loop से `a * 2` बेहतर क्यों हो सकता है?", [["It is a vectorized element-wise operation", "यह vectorized element-wise operation है"], ["It converts the array into a filename", "यह array को filename बनाता है"], ["It multiplies only the first item", "यह केवल पहला item गुणा करता है"], ["It runs the loop twice", "यह loop दो बार चलाता है"]], 0, "Vectorized operations express the element-wise calculation directly using NumPy's optimized implementation.", "Vectorized operation element-wise गणना सीधे व्यक्त कर NumPy का optimized implementation उपयोग करता है।", "Expected Practice"),
        q("numpy-basics", "Hard", "An array has 24 elements and must be reshaped into four columns. Which target shape is valid?", "Array में 24 elements हैं और उसे चार columns में reshape करना है। कौन-सा target shape valid है?", [["(6, 4)", "(6, 4)"], ["(5, 4)", "(5, 4)"], ["(4, 5)", "(4, 5)"], ["(24, 2)", "(24, 2)"]], 0, "Reshape preserves element count, and six times four equals 24.", "Reshape element count सुरक्षित रखता है और छह गुणा चार 24 है।", "Expected Practice"),
        q("numpy-basics", "Hard", "For array `a = [-2, 3, 0]`, what does the Boolean-indexing expression `a[a > 0]` select?", "Array `a = [-2, 3, 0]` के लिए Boolean-indexing expression `a[a > 0]` क्या चुनता है?", [["A selection containing only 3", "केवल 3 वाला चयन"], ["The scalar True", "Scalar True"], ["The shape tuple (3,)", "Shape tuple (3,)"], ["All original elements", "सभी मूल elements"]], 0, "The comparison forms a mask, and Boolean indexing returns entries where the mask is true.", "Comparison mask बनाता है और Boolean indexing true mask वाली entries लौटाता है।", "Expected Practice"),
        q("numpy-basics", "Hard", "Arrays with shapes `(2, 1)` and `(1, 3)` are added. What shape does broadcasting produce?", "Shapes `(2, 1)` और `(1, 3)` के arrays जोड़े जाते हैं। Broadcasting कौन-सा shape देता है?", [["(2, 3)", "(2, 3)"], ["(2, 1)", "(2, 1)"], ["(1, 3)", "(1, 3)"], ["The operation is invalid", "Operation अमान्य है"]], 0, "Each singleton dimension expands to match, producing two rows and three columns.", "हर singleton dimension फैलकर मेल खाता है और दो rows, तीन columns बनते हैं।", "Expected Practice"),
        q("oop", "Moderate", "A fixed organization name should be shared by all instances of a class. Where should it usually be defined?", "Class के सभी instances में साझा स्थिर organization name कहाँ define करना चाहिए?", [["As a class attribute", "Class attribute के रूप में"], ["As a local variable in each method", "हर method के local variable के रूप में"], ["Inside a file handle", "File handle के भीतर"], ["As the return value of `__init__`", "`__init__` के return value के रूप में"]], 0, "A class attribute is associated with the class and shared unless an instance overrides it.", "Class attribute class से जुड़ा और साझा होता है, जब तक instance उसे override न करे।", "Expected Practice"),
        q("oop", "Moderate", "When an instance method is called on an object, what does its first parameter conventionally named `self` refer to?", "Object पर instance method call होने पर पहला parameter `self` किसे refer करता है?", [["The particular instance receiving the call", "Call प्राप्त करने वाला वही instance"], ["The module filename", "Module filename"], ["Every class instance", "हर class instance"], ["The method's source string", "Method की source string"]], 0, "Python supplies the object as the first argument to a bound instance method.", "Python bound instance method के पहले argument के रूप में object देता है।", "Expected Practice"),
        q("oop", "Moderate", "A subclass adds an attribute during initialization but must preserve the parent's setup. What should it call?", "Subclass initialization में attribute जोड़ते हुए parent का setup सुरक्षित रखना है। उसे क्या call करना चाहिए?", [["`super().__init__(...)` with suitable arguments", "उचित arguments के साथ `super().__init__(...)`"], ["`print(__init__)`", "`print(__init__)`"], ["The parent class's filename", "Parent class का filename"], ["A new module for each object", "हर object के लिए नया module"]], 0, "super provides access to the next implementation in the method resolution order.", "super method resolution order में अगले implementation तक पहुँच देता है।", "Expected Practice"),
        q("oop", "Moderate", "A method uses an object's attributes to calculate a value without changing them. What does this illustrate?", "एक method object attributes से मान निकालता है लेकिन उन्हें बदलता नहीं। यह क्या दर्शाता है?", [["Behavior operating on object state", "Object state पर काम करने वाला behavior"], ["A separate class declaration", "अलग class declaration"], ["Conversion to a module", "Module में conversion"], ["Automatic creation of every instance", "हर instance का स्वतः निर्माण"]], 0, "Methods define object-associated behavior and can use attributes in their calculations.", "Methods object से जुड़ा behavior परिभाषित करते हैं और गणना में attributes उपयोग कर सकते हैं।", "Expected Practice"),
        q("oop", "Moderate", "A `Car` object contains an `Engine` object and delegates starting to it. What relationship is shown?", "`Car` object में `Engine` object है और start करना उसे सौंपा गया है। कौन-सा संबंध दिखता है?", [["Composition, a has-a relationship", "Composition, has-a संबंध"], ["Inheritance, an is-a relationship", "Inheritance, is-a संबंध"], ["Only overriding", "केवल overriding"], ["Array broadcasting", "Array broadcasting"]], 0, "Composition combines collaborating objects; a car has an engine rather than being one.", "Composition सहयोगी objects जोड़ता है; car के पास engine है, car engine नहीं है।", "Expected Practice"),
        q("oop", "Hard", "A function calls `render()` on objects of different classes without checking their types. Which OOP idea supports this?", "एक function अलग classes के objects पर type जाँचे बिना `render()` call करता है। कौन-सा OOP विचार इसका समर्थन करता है?", [["Polymorphism through compatible behavior", "संगत behavior के माध्यम से polymorphism"], ["File truncation", "File truncation"], ["Tuple immutability", "Tuple immutability"], ["Global scope", "Global scope"]], 0, "Polymorphism allows different object types to respond to the same operation.", "Polymorphism अलग object types को समान operation का उत्तर देने देता है।", "Expected Practice"),
        q("oop", "Hard", "An overridden method also needs the parent's behavior before adding specialization. What is the appropriate approach?", "Overridden method को specialization जोड़ने से पहले parent का behavior भी चाहिए। उचित तरीका क्या है?", [["Call the parent implementation via `super()` then extend it", "`super()` से parent implementation बुलाकर उसे बढ़ाएँ"], ["Remove the parent from the hierarchy", "Hierarchy से parent हटाएँ"], ["Call the method through an old variable name", "पुराने variable नाम से method बुलाएँ"], ["Convert the instance to a list", "Instance को list में बदलें"]], 0, "Calling the parent method preserves shared behavior while the subclass adds its specialization.", "Parent method बुलाने से साझा behavior सुरक्षित रहता है और subclass विशेष behavior जोड़ती है।", "Expected Practice"),
        q("oop", "Hard", "A class exposes `deposit(amount)` and rejects negative amounts instead of allowing arbitrary balance replacement. Why is this safer?", "Class `deposit(amount)` देता है और arbitrary balance बदलने के बजाय negative amount अस्वीकार करता है। यह सुरक्षित क्यों है?", [["The method enforces an invariant when state changes", "State बदलते समय method invariant लागू करता है"], ["Methods make balance unreadable", "Methods balance को अपठनीय बनाते हैं"], ["Direct assignment is always slower", "Direct assignment हमेशा धीमा है"], ["The object no longer needs attributes", "Object को attributes नहीं चाहिए"]], 0, "A controlled method validates changes and preserves class invariants.", "नियंत्रित method बदलाव validate करके class invariants सुरक्षित रखता है।", "Expected Practice"),
        q("file-processing", "Moderate", "A program must read a file and report an error if the path is missing rather than create a new file. Which mode is appropriate?", "Program को file पढ़नी है और path न मिलने पर नई file बनाने की जगह error देना है। कौन-सा mode उचित है?", [["`r` read mode", "`r` read mode"], ["`w` write mode", "`w` write mode"], ["`a` append mode", "`a` append mode"], ["`x` exclusive-create mode", "`x` exclusive-create mode"]], 0, "Read mode expects an existing file and does not silently create it.", "Read mode में file मौजूद होनी चाहिए और यह चुपचाप file नहीं बनाता।", "Expected Practice"),
        q("file-processing", "Moderate", "A log must preserve old entries and add each new entry at its end. Which mode is designed for this?", "Log में पुराने entries सुरक्षित रखकर हर नया entry अंत में जोड़ना है। कौन-सा mode इसके लिए है?", [["Append mode `a`", "Append mode `a`"], ["Write mode `w`", "Write mode `w`"], ["Read mode `r`", "Read mode `r`"], ["Exclusive mode `x`", "Exclusive mode `x`"]], 0, "Append mode writes at the end and preserves existing contents.", "Append mode अंत में लिखता है और मौजूदा सामग्री सुरक्षित रखता है।", "Expected Practice"),
        q("file-processing", "Moderate", "To decode non-ASCII text consistently, how should a program specify its encoding when opening a file?", "Non-ASCII text को एकसमान decode करने के लिए file खोलते समय encoding कैसे specify करें?", [["Pass an explicit encoding such as `encoding=\"utf-8\"`", "`encoding=\"utf-8\"` जैसी encoding दें"], ["Change the extension to `.py`", "Extension `.py` करें"], ["Use append mode only", "केवल append mode लें"], ["Set the pointer to zero", "Pointer zero करें"]], 0, "An explicit encoding makes the byte-to-text decoding choice clear and portable.", "Explicit encoding bytes से text decoding स्पष्ट और portable बनाता है।", "Expected Practice"),
        q("file-processing", "Moderate", "Which file method reports the current stream position so the program can later return to it?", "बाद में वापस लौटने के लिए वर्तमान stream position कौन-सा file method बताता है?", [["tell()", "tell()"], ["close()", "close()"], ["write()", "write()"], ["truncate()", "truncate()"]], 0, "tell returns the current position, which can later be passed to seek.", "tell वर्तमान position देता है जिसे बाद में seek में दिया जा सकता है।", "Expected Practice"),
        q("file-processing", "Moderate", "Which call reads up to the next five characters from an open text file?", "खुली text file से अगले पाँच characters तक पढ़ने के लिए कौन-सा call है?", [["file.read(5)", "file.read(5)"], ["file.write(5)", "file.write(5)"], ["file.seek(5)", "file.seek(5)"], ["file.close(5)", "file.close(5)"]], 0, "read(size) returns up to the requested number of characters from the current position.", "read(size) वर्तमान position से माँगी गई संख्या तक characters देता है।", "Expected Practice"),
        q("file-processing", "Hard", "A new output file should be created, but an existing file must never be overwritten. Which mode best expresses this?", "नई output file बनानी है, लेकिन मौजूदा file overwrite नहीं होनी चाहिए। कौन-सा mode सही है?", [["Exclusive creation mode `x`", "Exclusive creation mode `x`"], ["Write mode `w`", "Write mode `w`"], ["Append mode `a`", "Append mode `a`"], ["Read mode `r`", "Read mode `r`"]], 0, "Exclusive creation raises an error if the path already exists.", "Exclusive creation में path पहले से मौजूद हो तो error आता है।", "Expected Practice"),
        q("file-processing", "Hard", "A program saves a value returned by `tell()` and later passes it to `seek()`. What is the intended result?", "Program `tell()` से मिला मान सहेजकर बाद में `seek()` को देता है। अपेक्षित परिणाम क्या है?", [["Move the file pointer back to the saved position", "File pointer को सहेजी position पर लौटाना"], ["Delete all earlier file data", "पहले का सारा file data हटाना"], ["Change the encoding", "Encoding बदलना"], ["Switch automatically to write mode", "स्वतः write mode में जाना"]], 0, "seek changes stream position and a saved tell value permits rereading from that point.", "seek stream position बदलता है और सहेजा tell मान उस स्थान से फिर पढ़ने देता है।", "Expected Practice"),
        q("file-processing", "Hard", "An exception occurs inside a `with open(...)` block while a file is being processed. What should happen to the file resource?", "`with open(...)` block में file process करते समय exception आता है। File resource के साथ क्या होना चाहिए?", [["The context manager closes it as the exception propagates", "Exception आगे जाते समय context manager इसे बंद करता है"], ["It remains open until restart", "यह restart तक खुली रहती है"], ["The exception becomes end-of-file", "Exception end-of-file बन जाता है"], ["It reopens in write mode", "यह write mode में फिर खुलती है"]], 0, "The context manager performs cleanup when the block exits, including through an exception.", "Context manager block से बाहर निकलते समय cleanup करता है, exception होने पर भी।", "Expected Practice")
    ];
}(window));
